-- LOCAL DEV ONLY: emulates the read-only business view [dbo].[Property].
-- The real Property view lives on the DIP server; this stand-in lets the
-- Land Register be exercised locally. Never run against production.
-- Mirrors the view's columns incl. LeaseNo, LandLordCode, CompanyName, ContactName, EmailAddress.
SET NOCOUNT ON;
IF OBJECT_ID('dbo.Property','U') IS NOT NULL DROP TABLE dbo.Property;
GO
CREATE TABLE dbo.Property (
    Id           INT           NOT NULL PRIMARY KEY,
    CategoryName NVARCHAR(200) NULL,
    PropertyCode NVARCHAR(80)  NOT NULL,
    BuildingName NVARCHAR(250) NULL,
    LeaseNo      NVARCHAR(50)  NULL,
    LandLordCode NVARCHAR(50)  NULL,
    CompanyName  NVARCHAR(200) NULL,
    ContactName  NVARCHAR(150) NULL,
    EmailAddress NVARCHAR(200) NULL
);
GO
SELECT COUNT(*) AS Rows, COUNT(CompanyName) AS WithCompany FROM dbo.Property;